const input = $input.first().json;
const config = $('Config').first().json;
const chatId = String(input?.message?.chat?.id ?? '').trim();
const rawText = String(input?.message?.text ?? '').trim();
const firstWord = rawText ? rawText.split(/\s+/)[0] : '';
const normalized = firstWord.replace(/@[A-Za-z0-9_]+$/i, '').toLowerCase();
const allowed = ['/status', '/uptime', '/telemetria', '/testardlq'];
const command = allowed.includes(normalized) ? normalized : 'help';
const backendBaseUrl = String(config?.BACKEND_BASE_URL ?? '').trim().replace(/\/+$/, '');
const backendConfigured = Boolean(backendBaseUrl) && backendBaseUrl !== '<BACKEND_BASE_URL>' && /^https?:\/\/[^\s]+$/i.test(backendBaseUrl);
return [{ json: { chatId, command, rawText, backendBaseUrl, backendConfigured } }];

const ctx = $('Normalizar comando').first().json;
const res = $input.first().json;
const escapeMdV2 = (v) => String(v ?? '').replace(/([\\_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
const escapeCode = (v) => String(v ?? '').replace(/([\\`])/g, '\\$1');
const safeSliceEscaped = (str, maxLen) => {
  if (maxLen <= 0) return '';
  if (str.length <= maxLen) return str;
  let sliced = str.slice(0, maxLen);
  let backslashes = 0;
  for (let i = sliced.length - 1; i >= 0 && sliced[i] === '\\'; i--) backslashes++;
  if (backslashes % 2 === 1) sliced = sliced.slice(0, -1);
  return sliced;
};
const rawCode = res?.statusCode ?? res?.error?.httpCode ?? res?.error?.statusCode;
const statusCode = typeof rawCode === 'number' && Number.isFinite(rawCode) ? rawCode : (typeof rawCode === 'string' && /^\d{3}$/.test(rawCode) ? Number(rawCode) : 0);
const hasPinnedData = res && typeof res === 'object' && ('status' in res || (typeof res.body === 'object' && res.body !== null && 'status' in res.body));
let text = '';
if (statusCode === 401) {
  text = '🔒 Chave de suporte inválida\\.';
} else if (statusCode === 503) {
  text = '⚙️ Suporte não configurado no backend\\.';
} else if ((!ctx.backendConfigured && !hasPinnedData) || res?.error || (statusCode > 0 && (statusCode < 200 || statusCode >= 300))) {
  text = '⚠️ Backend indisponível \\(túnel?\\)';
} else {
  const data = (res && typeof res.body === 'object' && res.body !== null && 'statusCode' in res) ? res.body : res;
  if (!data || typeof data.status !== 'string' || !Array.isArray(data.dependencies)) {
    text = '⚠️ Backend indisponível \\(túnel?\\)';
  } else {
    const statusEmoji = data.status === 'ok' ? '✅' : (data.status === 'degraded' ? '⚠️' : '🔴');
    const lines = [
      '📊 *Status do Sistema*',
      `*Geral:* ${statusEmoji} \`${escapeCode(data.status)}\``,
    ];
    if (typeof data.checked_at === 'string' && data.checked_at.trim()) {
      lines.push(`*Verificado em:* ${escapeMdV2(data.checked_at.trim())}`);
    }
    lines.push('*Dependências:*');
    if (data.dependencies.length === 0) {
      lines.push('_Nenhuma dependência reportada_');
    } else {
      for (const dep of data.dependencies) {
        const depState = String(dep?.state ?? 'desconhecido');
        const depEmoji = depState === 'closed' ? '🟢' : (depState === 'half_open' ? '🟡' : '🔴');
        lines.push(`• \`${escapeCode(dep?.name ?? 'desconhecida')}\`: ${depEmoji} ${escapeMdV2(depState)}`);
      }
    }
    text = safeSliceEscaped(lines.join('\n'), 4096);
  }
}
return [{ json: { chatId: ctx.chatId, text } }];

